int handle_client_message(gpointer data) {
    Client *client = (Client *)data;

    if (!client->tls_handshake_complete) {
        int result = perform_tls_handshake(client);
        if (result != 0) {
            return -1;
        }
        notify_other_clients_of_connection(client);
        client->tls_handshake_complete = true;
    }

    while (1) {
        char buffer[1024];
        ssize_t bytes_received = receive_message(client->tls_socket, buffer, sizeof(buffer));

        if (bytes_received <= 0) {
            if (bytes_received == 0) {
                handle_client_disconnection(client);
            }
            break;
        }

        process_received_message(client, buffer, bytes_received);
    }

    return 0;
