#include <glib.h>
#include <gnutls/gnutls.h>

int handle_client_message(gpointer data) {
    ClientData *client = (ClientData *)data;
    int ret;

    if (!client->tls_handshake_complete) {
        ret = gnutls_handshake(client->tls_session);
        if (ret < 0) {
            g_warning("TLS handshake failed: %s", gnutls_strerror(ret));
            return -1;
        }
        client->tls_handshake_complete = TRUE;
        notify_other_clients(client);
    }

    while (TRUE) {
        ssize_t msg_len = gnutls_record_check_pending(client->tls_session);
        if (msg_len <= 0)
            break;

        char buffer[4096];
        ret = gnutls_record_recv(client->tls_session, buffer, sizeof(buffer));
        if (ret < 0) {
            if (ret == GNUTLS_E_PREMATURE_TERMINATION || ret == GNUTLS_E_AGAIN || ret == GNUTLS_E_INTERRUPTED) {
                break;
            }
            g_warning("Error receiving message: %s", gnutls_strerror(ret));
            return -1;
        }

        if (process_message(client, buffer, ret) != 0) {
            g_warning("Failed to process message");
            return -1;
        }
    }

    if (client->disconnected) {
        handle_client_disconnection(client);
        return -1;
    }

    return 0;
}

int handle_client_message(gpointer data) {
    Client *client = (Client *)data;

    if (!client->tls_handshake_complete) {
        int handshake_result = perform_tls_handshake(client);
        if (handshake_result != 0) {
            return -1;
        }
        client->tls_handshake_complete = true;
        notify_other_clients_of_connection(client);
    }

    if (client->is_disconnected) {
        return -1;
    }

    while (client->message_buffer_has_data) {
        Message *msg = extract_next_message(client);
        if (!msg) {
            break;
        }

        update_client_details(client, msg);
        int process_result = process_message(msg, client);

        if (process_result != 0) {
            client->is_disconnected = true;
            return -1;
        }
    }

    return 0;
}

int handle_client_message(gpointer data) {
    ClientData *client = (ClientData *)data;

    if (!client->tls_handshake_complete) {
        if (perform_tls_handshake(client) != 0) {
            return -1;
        }
        client->tls_handshake_complete = true;
        notify_clients_of_handshake_success(client);
    }

    while (client->message_queue_has_data) {
        Message *msg = dequeue_message(client->message_queue);
        if (!msg) {
            break;
        }

        if (is_message_valid(msg)) {
            update_client_details(client, msg);
            if (process_message(msg, client) != 0) {
                free_message(msg);
                return -1;
            }
        } else {
            handle_invalid_message(msg, client);
        }

        free_message(msg);
    }

    if (is_client_disconnected(client)) {
        cleanup_client_connection(client);
        return -1;
    }

    return 0;
}
